    \mathrm{CPL}^{+}\vdash\sigma
    \quad\Longleftrightarrow\quad
    \mathrm{CPL}\vdash\sigma
    \qquad(\sigma\in\mathcal L_{\mathsf P}).
  \]}
  \modelconsequence{Every extended formula has a base-language equivalent.}
\end{modelconsequences}

